<template>
  <div class="rv-root">
    <!-- ── Loading ──────────────────────────────────────────────────── -->
    <div v-if="loading" class="rv-loading">
      <v-progress-circular indeterminate color="primary" size="48"></v-progress-circular>
      <span>Loading your details…</span>
    </div>

    <!-- ── Load-time guard failures ─────────────────────────────────── -->
    <v-container v-else-if="loadError" class="mt-8">
      <v-alert type="error" outlined prominent border="left">
        <v-row align="center">
          <v-col class="grow">
            <div class="font-weight-bold text-h6 mb-1">Unable to Load Your Details</div>
            <div>{{ loadError }}</div>
          </v-col>
          <v-col class="shrink">
            <v-icon size="48" color="error">mdi-alert-circle-outline</v-icon>
          </v-col>
        </v-row>
      </v-alert>
    </v-container>

    <template v-else>
      <v-navigation-drawer
        app
        clipped
        permanent
        right
        class="primary darken-1 white--text"
        style="z-index: 3;"
      >
        <v-list class="white--text">
          <v-list-item>
            <v-btn class="secondary" dark small @click="goBack">
              <v-icon small left>mdi-close-circle-outline</v-icon>Cancel
            </v-btn>
            <v-spacer></v-spacer>
            <v-btn
              :disabled="saving || ageOutOfRange"
              :loading="saving"
              class="success darken-1"
              dark
              small
              @click="submitForm"
            >
              <v-icon small left>mdi-content-save</v-icon>Submit
            </v-btn>
          </v-list-item>

          <v-divider color="white"></v-divider>
          <v-subheader class="white--text"><h2>Details</h2></v-subheader>

          <v-list-item>
            <v-list-item-content class="white--text">
              <v-list-item-title class="text-uppercase">
                <h4>Your Current Age</h4>
              </v-list-item-title>
              <v-list-item-subtitle class="white--text">
                <span v-if="currentAge !== null">{{ currentAge }} years</span>
                <span v-else>Not available on file</span>
              </v-list-item-subtitle>
            </v-list-item-content>
          </v-list-item>

          <v-list-item>
            <v-list-item-content class="white--text">
              <v-list-item-title class="text-uppercase">
                <h4>Eligibility</h4>
              </v-list-item-title>
              <v-list-item-subtitle class="white--text">
                Age 50 to 59 at the expected retirement date
              </v-list-item-subtitle>
            </v-list-item-content>
          </v-list-item>
        </v-list>
      </v-navigation-drawer>

      <div class="rv-topbar">
        <v-btn text small @click="goBack">
          <v-icon left small>mdi-arrow-left</v-icon>Back
        </v-btn>
      </div>

      <v-container class="rv-form-wrap">
        <v-card outlined class="slv-card mb-5 mx-auto" max-width="720">
          <v-card-title class="primary darken-1 white--text text-uppercase font-weight-bold d-flex align-center py-3">
            <v-icon left color="white">mdi-account-clock</v-icon>
            Early Retirement Request
          </v-card-title>
          <v-card-text class="pa-6">
            <!-- ── Current age context ────────────────────────────────── -->
            <div class="rv-age-banner mb-5">
              <v-icon size="28" color="primary" class="mr-3">mdi-cake-variant-outline</v-icon>
              <div>
                <div class="rv-field-label">YOUR CURRENT AGE</div>
                <div class="rv-age-value">
                  <span v-if="currentAge !== null">{{ currentAge }} years</span>
                  <span v-else>Not available on file</span>
                </div>
              </div>
            </div>

            <v-alert type="info" dense outlined class="mb-5">
              <v-icon small class="mr-1">mdi-information-outline</v-icon>
              Early retirement requests are only approved for staff whose age
              falls between <strong>50 and 59</strong> at the expected
              retirement date. This is checked automatically when you submit.
            </v-alert>

            <v-form ref="form" v-model="valid">
              <div class="rv-field-label mb-2">REASON *</div>
              <v-textarea
                v-model="form.reason"
                outlined
                dense
                rows="4"
                placeholder="Explain why you are requesting early retirement"
                :rules="[(v) => !!(v && v.trim()) || 'Reason is required']"
              ></v-textarea>

              <div class="rv-field-label mb-2">EXPECTED RETIREMENT DATE *</div>
              <v-menu
                v-model="dateMenu"
                :close-on-content-click="false"
                offset-y
                min-width="290"
              >
                <template v-slot:activator="{ on }">
                  <v-text-field
                    v-model="form.expectedRetirementDate"
                    outlined
                    dense
                    readonly
                    prepend-inner-icon="mdi-calendar"
                    placeholder="YYYY-MM-DD"
                    v-on="on"
                    :rules="[
                      (v) => !!v || 'Expected retirement date is required',
                      () =>
                        !ageOutOfRange ||
                        `You must be between age 50 and 59 on this date (you would be ${ageAtRetirement})`,
                    ]"
                  ></v-text-field>
                </template>
                <v-date-picker
                  v-model="form.expectedRetirementDate"
                  @input="dateMenu = false"
                ></v-date-picker>
              </v-menu>
              <div
                class="rv-helper-note mb-4"
                :class="{ 'rv-helper-note--error': ageOutOfRange }"
              >
                <v-icon size="14" :color="ageOutOfRange ? '#dc2626' : '#a8a29e'">
                  {{ ageOutOfRange ? "mdi-alert-circle-outline" : "mdi-information-outline" }}
                </v-icon>
                For this request to be approved, you must be between
                <strong>age 50 and 59</strong> on this date
                <span v-if="ageAtRetirement !== null">
                  — you would be <strong>{{ ageAtRetirement }}</strong>.
                </span>
              </div>
            </v-form>
          </v-card-text>
          <v-card-actions class="pa-4 pt-0">
            <v-btn text small @click="goBack">Cancel</v-btn>
            <v-spacer></v-spacer>
            <v-btn color="primary" small :loading="saving" :disabled="saving" @click="submitForm">
              <v-icon left small>mdi-content-save</v-icon>Submit Request
            </v-btn>
          </v-card-actions>
        </v-card>
      </v-container>
    </template>

    <v-snackbar v-model="snackbar.show" :color="snackbar.color" top right :timeout="4000">
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";
import generalMixin from "../../mixins/general";

export default {
  name: "EarlyRetirementRequest",
  mixins: [processQuestionnaire, generalMixin],
  props: ["queries"],

  data() {
    return {
      // POST /fhir/QuestionnaireResponse with this.fhir = { reason,
      // expectedRetirementDate } — maps onto EarlyRetirementRequestProfile's
      // reason/expected-retirement-date extensions. practitioner/status/
      // event-date/user-reference are all set server-side by
      // earlyRetirementRequestWorkflow.js.
      url: "http://ihris.org/fhir/Questionnaire/early-retirement-request",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/early-retirement-request-profile",

      loading: true,
      loadError: null,
      currentAge: null,
      dob: null,

      valid: false,
      saving: false,
      dateMenu: false,

      form: {
        reason: "",
        expectedRetirementDate: null,
      },

      afterSaveMessage: "Early retirement request submitted successfully!",
      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    // Client-side hint only — the backend (earlyRetirementRequestWorkflow.js)
    // is the source of truth for the actual 50-59 eligibility check.
    ageAtRetirement() {
      if (!this.form.expectedRetirementDate) return null;
      return this.calcAge(this.dob, this.form.expectedRetirementDate);
    },

    // Mirrors the backend's own 50-59 eligibility check
    // (earlyRetirementRequestWorkflow.js) so an out-of-range date is caught
    // here instead of only surfacing as a rejection toast after submit.
    ageOutOfRange() {
      return (
        this.ageAtRetirement !== null &&
        (this.ageAtRetirement < 50 || this.ageAtRetirement > 59)
      );
    },
  },

  methods: {
    calcAge(birthDate, atDate) {
      if (!birthDate) return null;
      const dob = new Date(birthDate);
      const at = atDate ? new Date(atDate) : new Date();
      if (isNaN(dob.getTime()) || isNaN(at.getTime())) return null;
      let age = at.getFullYear() - dob.getFullYear();
      const m = at.getMonth() - dob.getMonth();
      if (m < 0 || (m === 0 && at.getDate() < dob.getDate())) {
        age--;
      }
      return age;
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    // Resolves the logged-in staff's own Practitioner record client-side,
    // same as the backend workflow does (Person -> ihris-practitioner-reference
    // -> Practitioner), so the current-age banner reflects the same record
    // the server will check on submit.
    async loadOwnPractitioner() {
      const id = this.loggedInStaff?.practitioner;
      if (!id) {
        this.loadError =
          "Unable to confirm that you are a staff member, please contact your system administrator.";
        return;
      }
      try {
        const res = await fetch(`/fhir/Practitioner/${id}`);
        if (!res.ok) {
          this.loadError = "Unable to load your staff record.";
          return;
        }
        const practitioner = await res.json();
        this.dob = practitioner.birthDate || null;
        this.currentAge = this.calcAge(this.dob);
      } catch (error) {
        console.error("Error loading practitioner:", error);
        this.loadError = "Unable to load your staff record.";
      }
    },

    async submitForm() {
      const valid = this.$refs.form.validate();
      if (!valid) {
        this.showSnackbar("Please complete all required fields.", "error");
        return;
      }

      this.saving = true;
      try {
        this.fhir = {
          reason: this.form.reason,
          expectedRetirementDate: this.form.expectedRetirementDate,
        };
        const data = await this.processFHIR();
        this.showSnackbar(this.afterSaveMessage, "success");

        // processFHIR() already parses this same tag internally (to drive
        // its own optional viewPage redirect, which we don't use here since
        // this feature's view page is a /custom/... route, not a named
        // "resource_view" route) — mirror that extraction to get the newly
        // created request's Basic id so we can go straight to its view page.
        const redirectTag = data?.meta?.tag?.find(
          (tag) => tag.system === "http://ihris.org/fhir/tags/resource",
        );
        const newRequestId = redirectTag?.code?.split("/")?.[1];

        setTimeout(() => {
          if (newRequestId) {
            this.$router.push({
              path: "/custom/early-retirement-view",
              query: {
                path: "/lesotho/components/early-retirement",
                request: newRequestId,
              },
            });
          } else {
            this.goBack();
          }
        }, 300);
      } catch (error) {
        // Backend rejections (duplicate pending request, age out of range,
        // etc.) surface via the processQuestionnaire mixin's own error
        // toast (this.$store.commit("setMessage", ...)) — nothing further
        // needed here.
        console.error("submitForm error:", error);
      } finally {
        this.saving = false;
      }
    },
  },

  async mounted() {
    await this.$nextTick();

    // Wait for generalMixin to finish loading loggedInStaff
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });

    await this.loadOwnPractitioner();
    this.loading = false;
  },
};
</script>

